begin;
select pg_advisory_xact_lock(hashtextextended('chem-h1-teacher-scope-20261005',0));
create temporary table h1_leaf_supplement as select * from jsonb_to_recordset($supplement$[{"id":"KC_H1_ELECTROLYTE","skill_id":"H1_ELECTROLYTE","expected_content":{"intro":"这一模块把“电解质分类—电离—离子反应—离子方程式”连成一条线：先知道溶液里真正有哪些粒子，再判断哪些粒子发生了反应。","skillId":"H1_ELECTROLYTE","version":2,"overview":["电解质判断先限化合物，再看物质本身能否在水中或熔融时产生离子。","强电解质在水中近乎完全电离，弱电解质部分电离；强弱与溶解性不是同一标准。","离子反应发生的常见推动力：生成沉淀、气体、弱电解质，或发生氧化还原等。","离子方程式按“写—拆—删—查”完成，并根据少量、过量和反应顺序确定产物。","离子检验和除杂都不是“报一个试剂名”：要把取样、排干扰、特征反应、现象、结论和新增杂质串成证据链。"],"sections":[{"items":[{"rule":"在水溶液中近乎完全电离，书写电离方程式时用“=”。常见强酸、强碱和大多数盐属于此类。","label":"强电解质","examples":["NaCl=Na⁺+Cl⁻：水中已溶解的NaCl几乎全部电离，不把溶液里的Na⁺、Cl⁻写成NaCl分子。"],"visualSteps":["NaCl溶于水","几乎全部电离成Na⁺、Cl⁻","以电离程度判强电解质"]},{"rule":"在水中只部分电离，存在动态平衡，书写时用可逆号。","label":"弱电解质","examples":["CH₃COOH⇌H⁺+CH₃COO⁻：醋酸溶液中同时有醋酸分子和离子，电离式用可逆符号。"],"visualSteps":["CH₃COOH进入水中","部分分子电离","分子和离子达到电离平衡"]},{"rule":"强弱说已溶解部分的电离程度；溶解性说有多少物质进入溶液。","label":"强弱与溶解性独立","examples":["BaSO₄难溶，但已溶解的部分几乎完全电离；“难溶”描述溶解量，“强”描述电离程度。"],"visualSteps":["BaSO₄在水中溶解很少","溶解的部分几乎完全电离","难溶与强电解质可以同时成立"]}],"title":"先看水溶液中真正存在的粒子","summary":"宏观上是一杯溶液，微观上可能有分子、离子和水分子共存。"},{"items":[{"rule":"离子结合成难溶物并从溶液的自由离子体系中离开。","label":"生成沉淀","examples":["BaCl₂溶液与Na₂SO₄溶液混合，Ba²⁺+SO₄²⁻=BaSO₄↓；Na⁺、Cl⁻不是这次沉淀反应的主体。"],"visualSteps":["溶液中Ba²⁺接触SO₄²⁻","形成难溶的BaSO₄","写Ba²⁺+SO₄²⁻=BaSO₄↓"]},{"rule":"生成气体逸出，或生成水、弱酸、弱碱等难电离物质，推动反应进行。","label":"生成气体或弱电解质","examples":["H⁺+HCO₃⁻=H₂O+CO₂↑，出现气泡；H⁺+OH⁻=H₂O则生成弱电解质水。两种推动因素分别核对。"],"visualSteps":["H⁺与HCO₃⁻相遇","生成H₂O和CO₂","CO₂逸出推动反应"],"children":[{"label":"生成气体为什么影响共存","rule":"在题给条件下，离子反应生成逸出的气体时，相关离子通常不能大量共存。","examples":["教学例子：酸性溶液中，CO₃²⁻与足量H⁺反应：CO₃²⁻+2H⁺=CO₂↑+H₂O。"],"reviewPointIndex":50},{"label":"生成弱电解质为什么影响共存","rule":"离子结合形成水或弱酸、弱碱等难电离物质时，相关离子通常不能大量共存。","examples":["教学例子：H⁺与OH⁻生成水：H⁺+OH⁻=H₂O。水不能再按强电解质拆成离子。"],"reviewPointIndex":51}]},{"rule":"离子之间发生电子转移，或形成稳定的复杂粒子，也可推动反应。","label":"氧化还原、络合等其他原因","caution":"陌生反应以题目给出的事实和信息为准。","examples":["Fe+2Fe³⁺=3Fe²⁺：没有沉淀或气体，仍可因电子转移发生离子反应。"],"visualSteps":["Fe接触Fe³⁺溶液","Fe失电子，Fe³⁺得电子","得到Fe+2Fe³⁺=3Fe²⁺"]}],"title":"离子反应为什么能够发生","summary":"本质是某些离子浓度显著减小或电子发生转移。"},{"items":[{"rule":"先保证反应物、产物、条件和计量数正确；分子方程式错，后面无法补救。","label":"写：写对分子方程式","examples":["稀盐酸与NaOH溶液反应先写HCl+NaOH=NaCl+H₂O。先把产物和计量数写对，再考虑后续拆离子。"],"visualSteps":["认出反应物HCl、NaOH","确定产物NaCl、H₂O","核对HCl+NaOH=NaCl+H₂O"]},{"rule":"水溶液中的可溶强电解质拆成离子；沉淀、气体、弱电解质、单质和氧化物通常保留化学式。","label":"拆：只拆该拆的","examples":["HCl、NaOH在稀水溶液中拆成H⁺、Cl⁻、Na⁺、OH⁻；H₂O不拆，CH₃COOH这样的弱酸也应保留化学式。"],"visualSteps":["HCl、NaOH是水溶液中的强电解质","分别拆成对应离子","生成的H₂O保留化学式"],"children":[{"label":"可溶性强电解质盐怎样拆","rule":"水溶液中的可溶性强电解质盐按实际离子和计量数拆开。","examples":["教学例子：Na₂SO₄溶液中的Na₂SO₄写成2Na⁺+SO₄²⁻，不能漏掉Na⁺的系数2。"],"reviewPointIndex":50},{"label":"难溶盐为什么不拆","rule":"难溶盐即使属于强电解质，在所写离子反应中作为固体或沉淀时仍保留化学式；强电解质身份不等于一定拆开。","examples":["教学例子：BaSO₄是难溶盐，可列为强电解质；Ba²⁺+SO₄²⁻=BaSO₄↓中的BaSO₄不拆。"],"reviewPointIndex":51},{"label":"强酸怎样拆","rule":"水溶液中的常见强酸按电离出的离子拆开；具体状态与题给反应条件优先。","examples":["教学例子：稀盐酸中的HCl拆成H⁺和Cl⁻。这里拆的是溶质HCl，不能把整个盐酸混合物当一种化合物。"],"reviewPointIndex":52},{"label":"可溶性强碱怎样拆","rule":"水溶液中的可溶性强碱按实际离子和计量数拆开。","examples":["教学例子：NaOH溶液中的NaOH写成Na⁺+OH⁻；可溶性强碱Ba(OH)₂写成Ba²⁺+2OH⁻。"],"reviewPointIndex":53},{"label":"弱电解质为什么不拆","rule":"弱酸、弱碱等弱电解质在通常的离子方程式中保留化学式。","examples":["教学例子：醋酸与NaOH反应写CH₃COOH+OH⁻=CH₃COO⁻+H₂O，CH₃COOH不拆成H⁺和CH₃COO⁻。"],"reviewPointIndex":54},{"label":"气体在离子式中怎样写","rule":"气体在通常的离子方程式中保留实际化学式。","examples":["教学例子：酸与碳酸盐反应生成CO₂时，写CO₂↑，不把CO₂按离子拆开。"],"reviewPointIndex":55},{"label":"水在离子式中怎样写","rule":"水在通常的离子方程式中保留H₂O，不拆成H⁺和OH⁻。","examples":["教学例子：强酸与强碱的中和反应写H⁺+OH⁻=H₂O；不能把右侧的水重新拆开。"],"reviewPointIndex":56},{"label":"单质在离子式中怎样写","rule":"单质在通常的离子方程式中保留单质的实际化学式。","examples":["教学例子：Cl₂+2I⁻=2Cl⁻+I₂中，反应物Cl₂和生成物I₂均保留分子式。"],"reviewPointIndex":57}]},{"rule":"删去反应前后形式和数目都相同的离子，保留真正改变的粒子。","label":"删：删除旁观离子","examples":["Na⁺+OH⁻+H⁺+Cl⁻→Na⁺+Cl⁻+H₂O中，Na⁺和Cl⁻两侧不变，删后为H⁺+OH⁻=H₂O。"],"visualSteps":["比较反应前后的离子","Na⁺、Cl⁻两侧相同","约去后留下H⁺+OH⁻=H₂O"]},{"rule":"检查反应事实、原子守恒、电荷守恒和系数最简；氧化还原还要查电子守恒。","label":"查：四重检查","examples":["写Ba²⁺+SO₄²⁻=BaSO₄↓后，左侧总电荷为0，右侧也为0，Ba、S、O原子数分别守恒。"],"visualSteps":["确认BaSO₄确实为沉淀","核对Ba、S、O原子数","左侧+2与−2相抵，右侧电荷0","确认式子已化为最简整数比"],"children":[{"label":"离子式先查反应事实","rule":"方程式中的反应物、产物与反应条件必须符合实际反应；守恒正确不能代替反应事实正确。","examples":["教学例子：Fe与足量稀盐酸反应通常生成Fe²⁺，不能因为能配平就写成生成Fe³⁺的式子。"],"reviewPointIndex":50},{"label":"离子式怎样查原子守恒","rule":"分别数每一种元素的原子数，方程式两边必须相同。","examples":["教学例子：2H⁺+CO₃²⁻=CO₂↑+H₂O两边均有2H、1C、3O。"],"reviewPointIndex":51},{"label":"离子式怎样查电荷守恒","rule":"把每个离子的电荷乘以系数，再求每一侧的总电荷；两边必须相等。","examples":["教学例子：Ba²⁺+SO₄²⁻=BaSO₄↓左侧总电荷+2−2=0，右侧为0。"],"reviewPointIndex":52},{"label":"离子式怎样查系数与旁观离子","rule":"约去反应前后形式和数目均相同的旁观离子后，系数通常化为最简整数比。","examples":["教学例子：HCl与NaOH的离子式约去Na⁺、Cl⁻，得到H⁺+OH⁻=H₂O，不能继续保留Na⁺、Cl⁻。"],"reviewPointIndex":53},{"label":"氧化还原离子式还要查什么","rule":"氧化还原反应中，总失电子数必须等于总得电子数；不能把两边电子数相加当转移总数。","examples":["教学例子：2Fe²⁺+Cl₂=2Fe³⁺+2Cl⁻中，失、得电子均为2e⁻，转移数是2e⁻。"],"reviewPointIndex":54}]}],"title":"离子方程式“写—拆—删—查”","summary":"每一步都解决一个明确问题。"},{"items":[{"rule":"无色、透明、强酸性、强碱性、由水电离的H⁺浓度等条件先翻译成粒子限制。","label":"先读隐含条件","examples":["题目要求“无色透明溶液中大量共存”时，先留意Cu²⁺通常呈蓝色、MnO₄⁻呈紫色，不能漏看“无色”这个条件。"],"visualSteps":["圈出题目的“无色”","识别常见有色离子","排除明显含Cu²⁺或MnO₄⁻的选项"],"children":[{"label":"澄清透明是否排除有色离子","rule":"澄清透明描述溶液中没有使其浑浊的悬浮物，不等于溶液无色；单凭这一条件不能排除有色离子。","examples":["教学例子：CuSO₄溶液可以是蓝色且澄清透明，所以“澄清透明”不能直接排除Cu²⁺。"],"reviewPointIndex":50},{"label":"无色溶液怎样排除有色离子","rule":"题目明确要求无色时，通常不能大量存在会使该溶液显色的离子；还要符合所给介质等条件。","examples":["教学例子：无色溶液中不能大量存在通常显蓝色的Cu²⁺；不能把“透明”单独当作无色限制。"],"reviewPointIndex":51},{"label":"强酸性条件先排查什么","rule":"强酸性溶液中有较多H⁺，先检查给定离子是否会与H⁺显著反应。","examples":["教学例子：强酸性溶液中的CO₃²⁻会被H⁺转化，不能与大量H⁺共存。"],"reviewPointIndex":52},{"label":"强碱性条件先排查什么","rule":"强碱性溶液中有较多OH⁻，先检查给定离子是否会与OH⁻显著反应。","examples":["教学例子：Cu²⁺与OH⁻生成Cu(OH)₂沉淀，不能在该条件下同时大量存在。"],"reviewPointIndex":53}]},{"rule":"依次查沉淀、气体、弱电解质、氧化还原和题目给出的特殊反应。","label":"再逐对排查反应","examples":["同一溶液含Ba²⁺与SO₄²⁻会生成BaSO₄沉淀，因此二者不能大量共存。"],"visualSteps":["从离子组中找Ba²⁺、SO₄²⁻","二者结合生成BaSO₄沉淀","判定不能大量共存"],"children":[{"label":"怎样查沉淀型不能共存","rule":"两种离子在所给条件下生成难溶沉淀时，不能同时大量共存。","examples":["教学例子：Ba²⁺与SO₄²⁻生成BaSO₄沉淀，因此这对离子不能大量共存。"],"reviewPointIndex":50},{"label":"怎样查气体型不能共存","rule":"两种离子在所给条件下反应生成气体逸出时，通常不能同时大量共存。","examples":["教学例子：H⁺与足量HCO₃⁻反应生成CO₂和水：H⁺+HCO₃⁻=CO₂↑+H₂O。"],"reviewPointIndex":51},{"label":"怎样查弱电解质型不能共存","rule":"两种离子显著结合形成弱电解质时，不能在该条件下同时大量共存。","examples":["教学例子：H⁺与CH₃COO⁻主要结合生成CH₃COOH；不能只查有无沉淀、气体而漏掉弱酸。"],"reviewPointIndex":52},{"label":"共存题还需留意其他反应","rule":"沉淀、气体、弱电解质之外，还要核对题给氧化还原或特殊反应条件。","examples":["教学例子：Fe³⁺能氧化I⁻：2Fe³⁺+2I⁻=2Fe²⁺+I₂，二者不能据“无沉淀、无气体”就判为大量共存。"],"reviewPointIndex":53}]},{"rule":"痕量不等于能大量共存；题目要求的是所有给定离子在相同溶液中都有较大浓度。","label":"注意“少量存在”和“大量共存”","examples":["即使BaSO₄的溶解平衡中仍有极少量Ba²⁺和SO₄²⁻，也不能说这两种离子在该条件下能大量共存。"],"visualSteps":["BaSO₄存在溶解平衡","溶液仍有极少量相关离子","极少量存在不等于大量共存"]}],"title":"离子共存题的判断顺序","summary":"“能大量共存”就是在给定条件下不能发生显著反应。"},{"items":[{"rule":"把少量物质的化学计量数定为满足完全反应，再判断过量物质剩余。","label":"少量试剂","examples":["少量CO₂通入足量NaOH溶液：CO₂+2OH⁻=CO₃²⁻+H₂O。这里要先看哪种反应物相对过量。"],"visualSteps":["OH⁻相对充足、CO₂较少","按1份CO₂消耗2份OH⁻","产物以CO₃²⁻为主"]},{"rule":"继续反应可能生成新的粒子，离子方程式要写到题设终点。","label":"过量试剂","examples":["继续通入CO₂时，CO₃²⁻+CO₂+H₂O=2HCO₃⁻；不能仍把少量CO₂时的CO₃²⁻当作最终主要产物。"],"visualSteps":["继续通入过量CO₂","已生成的CO₃²⁻继续反应","转化为HCO₃⁻"]},{"rule":"先发生更有利或题设指定的反应；必要时分阶段写方程式，再按用量合并。","label":"多反应竞争","caution":"不能见到所有可能反应就一次性全部相加。","examples":["向含H⁺、Ca²⁺的溶液逐滴加CO₃²⁻，先考虑H⁺消耗CO₃²⁻放出CO₂，酸耗尽后再考虑CaCO₃沉淀。"],"visualSteps":["先确认溶液同时含H⁺、Ca²⁺","加入的CO₃²⁻先受酸影响","酸消耗完后再考虑CaCO₃沉淀"]}],"title":"少量、过量和反应顺序","summary":"用量不同会改变终点，必须先找限制量。"},{"items":[{"rule":"先另取少量待测液，再按需要预处理排除干扰，加入检验试剂并写出特征现象，最后只作证据能够支持的结论。检验不能直接在原样中反复加试剂，否则前一步新加的离子可能干扰后一步。","label":"检验题的完整句式","caution":"离子检验以福建高中常见特征反应为限；复杂未知样品仍需结合题给离子范围，不能凭单一颜色无限外推。","examples":["【示范：检验氯离子】另取少量待测液，先加稀硝酸酸化，再滴加AgNO₃溶液；若出现不溶于稀硝酸的白色沉淀，可支持含Cl⁻，反应为Ag⁺+Cl⁻=AgCl↓。"],"visualSteps":["另取样品","稀硝酸预处理","AgCl白色沉淀→结论"]},{"rule":"Ba²⁺能与多种阴离子生成沉淀，所以“加钡盐有白色沉淀”证据不唯一。高中常用先加稀盐酸酸化，排除CO₃²⁻、SO₃²⁻等会被酸转化的干扰，再加入BaCl₂观察是否仍有白色BaSO₄。","label":"硫酸根检验先处理同现象干扰","caution":"若题目给出Ag⁺等会与Cl⁻反应的特殊背景，预处理试剂需要重新选择或增加分样；不能机械照搬固定顺序。","examples":["【示范：检验硫酸根】另取待测液，先加稀盐酸；若无异常沉淀，再加BaCl₂溶液，出现白色沉淀且在酸性条件下不溶，可支持含SO₄²⁻，离子反应为Ba²⁺+SO₄²⁻=BaSO₄↓。"],"visualSteps":["先列“钡盐白沉淀”竞争者","酸化排除碳酸根等","BaSO₄证据落地"]},{"rule":"合格除杂剂要能与杂质反应完全、不能大量损耗目标物、过量试剂能够在后续清除、不能留下新的难除杂质。先把“杂质→沉淀/气体/弱电解质”画出来，再追踪新加入的每一种离子去了哪里。","label":"除杂剂的四个门槛","caution":"高中除杂答案以题给目标产物和可用试剂为准；“加入过量”只有在过量部分能被后续可靠除去时才合理。","examples":["【示范：粗盐溶液中除去硫酸根】向含少量Na₂SO₄的NaCl溶液加入适量BaCl₂，使SO₄²⁻转为BaSO₄沉淀并过滤；Cl⁻仍属于目标盐体系。若BaCl₂过量，还要继续设计步骤除去Ba²⁺，所以“适量”和后续检验不能省略。"],"visualSteps":["杂质SO₄²⁻→BaSO₄","过滤移出固相","追查Ba²⁺是否过量"]},{"rule":"把每个候选试剂会与哪些现有离子、新增离子反应列成箭头；若两个检验会互相引入目标离子，就必须分样。若是连续除杂，则按“先生成沉淀—过滤—再调条件”的顺序，避免沉淀重新溶解或新杂质累积。","label":"多离子任务先画干扰链","caution":"分样、顺序和试剂选择属于高中实验推理；不要求脱离题给范围设计完整仪器分析流程。","examples":["【示范：同一样品检验氯离子和硫酸根】应分成两份：一份用稀硝酸和AgNO₃检验Cl⁻；另一份用稀盐酸和BaCl₂检验SO₄²⁻。若先在同一份中加BaCl₂，就人为引入Cl⁻，之后的氯离子检验失去可信度。"],"visualSteps":["画“试剂→新增离子”箭头","发现BaCl₂引入Cl⁻","分样形成两条证据链"]}],"title":"离子检验、除杂与干扰链","summary":"检验追求证据唯一，除杂追求目标保留、杂质转化、试剂可清除。"},{"title":"先认清电解质的判断对象","items":[{"label":"先确认是不是化合物","rule":"电解质和非电解质的判断对象是化合物；化合物由两种或两种以上元素组成且属于纯净物。","examples":["教学例子：NaCl晶体是一种化合物；NaCl溶液含盐和水，是混合物。"],"visualSteps":["先判纯净物还是混合物","纯净物再看是否由多种元素组成"]},{"label":"能导电的单质不是电解质","rule":"单质不属于电解质或非电解质；单质能导电不能改变其分类对象。","examples":["教学例子：铜能靠自由电子导电，但铜是单质，既不是电解质也不是非电解质。"],"visualSteps":["先确认铜是单质","单质不进入电解质分类"]},{"label":"盐酸为什么不是电解质","rule":"盐酸是HCl的水溶液，属于混合物，不能称为电解质或非电解质；HCl这种化合物属于电解质。","examples":["教学例子：盐酸能导电，但分类时盐酸是混合物，氯化氢HCl才是所判断的电解质。"],"visualSteps":["盐酸含HCl与水，是混合物","判断电解质的是化合物HCl"]},{"label":"氯化钠溶液为什么不是电解质","rule":"氯化钠溶液是混合物，不属于电解质或非电解质；其中的NaCl这种化合物属于电解质。","examples":["教学例子：盐水能导电是因为有可移动离子，但不能因此把整个NaCl溶液判为电解质。"],"visualSteps":["盐水含NaCl与水，是混合物","化合物NaCl才属于电解质"]}],"summary":"先确认分类对象，再分开判断每个易错点；不把导电能力当作物质分类的通行证。"}],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","checkpoints":["我能解释强弱电解质与溶解性的区别。","我能列出离子反应发生的主要条件。","我知道哪些物质在离子方程式中通常不拆。","我遇到少量、过量时会先找限制量。","我能把离子检验写成完整证据链。","我选择除杂剂时会继续追踪过量试剂和新增离子。"],"sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。","visualSummary":{"kind":"flow","steps":[{"label":"限定化合物","caption":"01"},{"label":"列真实粒子","caption":"02"},{"label":"找反应推动力","caption":"03"},{"label":"写→拆→删","caption":"04"},{"label":"查事实/原子/电荷","caption":"05"}],"title":"离子反应完整路线"},"workedExamples":[{"path":"NaCl在水中以Na⁺、Cl⁻为主，是强电解质；CH₃COOH分子与少量H⁺、CH₃COO⁻共存，是弱电解质；蔗糖主要以分子存在，是非电解质。","labels":["强电解质完全电离","弱电解质部分电离","非电解质不电离","画真实粒子"],"substance":"NaCl、CH₃COOH和蔗糖的粒子图"},{"path":"混合后H⁺与OH⁻结合成难电离的H₂O，二者浓度显著降低；Na⁺、Cl⁻没有实质变化，是旁观离子。","labels":["列出溶液粒子","找显著减少粒子","生成弱电解质","识别旁观离子"],"substance":"盐酸与NaOH为什么反应"},{"path":"先写HCl+NaOH=NaCl+H₂O；把可溶强电解质拆为离子；删去两边相同的Na⁺、Cl⁻；得到H⁺+OH⁻=H₂O，并查事实、原子、电荷和最简系数。","labels":["写对分子式","拆强电解质","删旁观离子","四重检查"],"substance":"HCl+NaOH的写拆删查"},{"path":"先把“无色”排除有色离子，把“酸性”转成有大量H⁺；再逐对检查沉淀、气体、弱电解质和氧化还原。HCO₃⁻会与H⁺生成CO₂、H₂O，不能大量共存。","labels":["翻译隐含条件","逐对检查","写净离子反应","所有离子同时成立"],"substance":"无色酸性溶液能否共存"},{"path":"少量CO₂时OH⁻足量，终点以CO₃²⁻为主：CO₂+2OH⁻=CO₃²⁻+H₂O；过量CO₂继续把CO₃²⁻转为HCO₃⁻，总式为CO₂+OH⁻=HCO₃⁻。","labels":["定少量为1","判断谁过量","分阶段反应","按终点合并"],"substance":"CO₂少量与过量通入NaOH"},{"path":"分子方程式HCl+NaOH=NaCl+H₂O；HCl、NaOH、NaCl拆成离子；删去Na⁺、Cl⁻，得到H⁺+OH⁻=H₂O；原子和电荷都守恒。","labels":["写","拆","删","查"],"substance":"盐酸与NaOH"},{"path":"NaHCO₃、HCl、NaCl在水中拆写，但HCO₃⁻作为多原子离子整体保留；碳酸分解为CO₂和H₂O，最终HCO₃⁻+H⁺=CO₂↑+H₂O。","labels":["HCO₃⁻不能错拆","气体保留分子式","查电荷0=0"],"substance":"NaHCO₃与盐酸"},{"path":"另取样品→根据候选离子排干扰→加入特异性较好的试剂→记录现象→写离子方程式→把结论限定为“可支持检出”。","labels":["取样","排干扰","特征现象","边界结论"],"substance":"离子证据链模板"}]},"children":[{"label":"难溶碱为什么不拆","rule":"难溶碱在通常的离子方程式中保留实际化学式，不能把难溶碱当作溶液中的可溶性强碱拆成金属离子和OH⁻。","examples":["教学例子：Cu(OH)₂与稀盐酸反应写Cu(OH)₂+2H⁺=Cu²⁺+2H₂O；Cu(OH)₂不能拆成Cu²⁺和2OH⁻。"],"caution":"判断的是题给物质的实际形态和溶解性，不是见到氢氧根就一律拆开。","reviewPointIndex":58},{"label":"氧化物在离子式中怎样写","rule":"高中通常的水溶液离子方程式中，氧化物保留化学式，不拆成金属离子和O²⁻；反应后的可溶性强电解质另按规则拆开。","examples":["教学例子：CuO与稀硫酸反应写CuO+2H⁺=Cu²⁺+H₂O；CuO不拆，而产物CuSO₄在溶液中拆成Cu²⁺和SO₄²⁻，SO₄²⁻为旁观离子。"],"caution":"不要在通常的水溶液离子式中写出游离的O²⁻。","reviewPointIndex":59}],"items":[{"label":"溶液导电是否来自物质自身电离","rule":"判定一种化合物为电解质，必须是该物质自身在水溶液中或熔融时产生可自由移动的离子。若先与水反应生成另一物质，再由生成物电离，不能把这种导电归给原化合物自身。","examples":["教学例子：CO₂溶于水后生成H₂CO₃，电离产生离子的是H₂CO₃；CO₂自身属于非电解质。"],"caution":"不能只凭“把它放进水里后溶液导电”判定它为电解质。","summary":"先查是谁产生离子，再判原化合物的电解质身份。","visualSteps":["CO₂先与水反应生成H₂CO₃","生成物电离不等于CO₂自身电离"]},{"label":"电解质一定处处都导电吗","rule":"电解质身份与某一状态下是否导电是两个判断。NaCl等离子晶体中的离子不能自由移动时不导电，但该化合物在水溶液中或熔融时能自身产生自由移动离子，因此仍是电解质。","examples":["教学例子：NaCl晶体不导电，熔融NaCl能导电；两种状态中的NaCl都属于电解质。"],"caution":"“当前不导电”不等于“非电解质”，不要把固态盐排除。","summary":"把物质身份与当前状态是否导电分开判断。","visualSteps":["NaCl晶体中的离子不能自由移动","熔融NaCl有自由移动离子，NaCl仍属电解质"]},{"label":"强电解质溶液一定更导电吗","rule":"强弱电解质描述已溶解部分的电离程度；溶液导电还与自由移动离子的浓度、电荷、温度等条件有关。条件未给全时，不能只按强弱电解质排序溶液导电能力。","examples":["教学例子：只给“NaCl是强电解质、醋酸是弱电解质”，不告诉浓度等条件，不能断定NaCl溶液一定更导电。"],"caution":"强电解质不等于浓溶液；“电离完全”和“离子总量多”不是一个概念。","summary":"电离程度与溶液中的自由离子浓度分开比较。","visualSteps":["强弱看已溶解部分的电离程度","导电还查浓度、离子电荷与温度等条件"]}]}]$supplement$::jsonb) as x(id text,skill_id text,expected_content jsonb,children jsonb,items jsonb);
select c.id from public.chem_knowledge_cards c join h1_leaf_supplement s using(id) for update of c;
do $guard$ begin
 if (select count(*) from h1_leaf_supplement)<>1 or exists(select 1 from h1_leaf_supplement s left join public.chem_knowledge_cards c using(id) where c.id is null or c.skill_id<>s.skill_id or c.review_status<>'approved' or c.structured_content is distinct from s.expected_content) then raise exception 'H1 supplement exact post-publication baseline changed';end if;
 if exists(select 1 from h1_leaf_supplement s where jsonb_array_length(s.expected_content#>'{sections,2,items,1,children}')<>8 or jsonb_array_length(s.expected_content#>'{sections,6,items}')<>4 or exists(select 1 from jsonb_array_elements(s.expected_content#>'{sections,2,items,1,children}') n where (n->>'reviewPointIndex')::integer in(58,59))) then raise exception 'H1 reserved stable append slots changed';end if;
end $guard$;
update public.chem_knowledge_cards c set structured_content=jsonb_set(jsonb_set(c.structured_content,'{sections,2,items,1,children}',(c.structured_content#>'{sections,2,items,1,children}')||s.children),'{sections,6,items}',(c.structured_content#>'{sections,6,items}')||s.items) from h1_leaf_supplement s where c.id=s.id;
do $validate$ begin
 if exists(select 1 from public.chem_knowledge_cards c join h1_leaf_supplement s using(id) where jsonb_array_length(c.structured_content#>'{sections,2,items,1,children}')<>10 or jsonb_array_length(c.structured_content#>'{sections,6,items}')<>7 or (c.structured_content#>'{sections,2,items,1,children}')->0 is distinct from (s.expected_content#>'{sections,2,items,1,children}')->0) then raise exception 'H1 append result validation failed';end if;
end $validate$;
select c.id,encode(extensions.digest(convert_to(c.structured_content::text,'UTF8'),'sha256'),'hex') structured_content_sha from public.chem_knowledge_cards c join h1_leaf_supplement s using(id);
commit;
